"use client";

import { useEffect, useState } from "react";
import AlertSidebar from "@/components/AlertSidebar";
import StreamNode from "@/components/StreamNode";
import StreamDialog from "@/components/StreamDialog";
import { PlusSquare, RefreshCw } from "lucide-react";
import { useTelemetry } from "@/context/TelemetryContext";

export default function LiveStreamPage() {
    const { logSysEvent } = useTelemetry();

    const [streams, setStreams] = useState<any[]>([]);
    const [alerts, setAlerts] = useState<any[]>([]);
    const [isDialogOpen, setIsDialogOpen] = useState(false);

    const fetchStreams = async () => {
        try {
            const res = await fetch("http://localhost:8000/api/streams");
            const data = await res.json();
            if (data.streams) setStreams(data.streams);
        } catch (err) {
            console.error("Failed to fetch streams", err);
        }
    };

    useEffect(() => {
        fetchStreams();
        const interval = setInterval(fetchStreams, 5000);
        return () => clearInterval(interval);
    }, []);

    const handleDeleteStream = async (id: string, cascadeDelete: boolean = true) => {
        try {
            if (cascadeDelete) {
                await fetch(`http://localhost:8000/api/streams/${id}`, { method: "DELETE" });
            }
            logSysEvent(`[WARN] SENSOR PROXY ${id.substring(0, 6).toUpperCase()} TERMINATED`);
            fetchStreams();
        } catch (err) {
            console.error("Failed to delete", err);
        }
    };

    const handleDetections = (detections: any[], timestamp: number) => {
        const threats = detections.filter(
            (d: any) => ["rifle", "handgun", "knife", "weapon"].includes(d.class_name) && d.confidence >= 0.45
        );
        const activeEvents = [...threats];

        if (activeEvents.length > 0) {
            setAlerts(prev => {
                let updated = [...prev];
                activeEvents.forEach(event => {
                    const existingIdx = updated.findIndex(a =>
                        a.class_name === event.class_name &&
                        a.endTimestamp !== undefined &&
                        (timestamp - a.endTimestamp) <= 3000
                    );

                    if (existingIdx !== -1) {
                        updated[existingIdx] = {
                            ...updated[existingIdx],
                            endTimestamp: Math.max(updated[existingIdx].endTimestamp, timestamp),
                            confidence: Math.max(updated[existingIdx].confidence, event.confidence)
                        };
                    } else {
                        updated.unshift({
                            id: Date.now() + Math.random(),
                            class_name: event.class_name,
                            confidence: event.confidence,
                            startTimestamp: timestamp,
                            endTimestamp: timestamp
                        });
                    }
                });
                return updated.slice(0, 50);
            });
        }
    };

    const primaryStream = streams[0] || null;
    const secondaryStreams = streams.slice(1);
    const placeholders = Array.from({ length: Math.max(0, 3 - streams.length) });

    return (
        <div className="flex gap-6 h-[calc(100vh-8rem)] font-mono uppercase tracking-widest text-[#FFF]">

            <div className="flex-1 flex flex-col gap-6">

                <div className="flex items-center justify-between border-[2px] border-[var(--color-iron)] bg-black p-4">
                    <div className="flex items-center gap-4">
                        <span className="font-bold border-b-[2px] border-white pb-1">[ MATRIX_GRID_CONTROL ]</span>
                        <div className={`px-2 py-1 text-[10px] font-bold border flex items-center gap-2 ${streams.length > 0 ? 'border-[var(--color-alert)] text-[var(--color-alert)] bg-[var(--color-alert)]/10' : 'border-[var(--color-iron)] text-[var(--color-silica)]'}`}>
                            {streams.length > 0 && <span className="w-2 h-2 bg-[var(--color-alert)] animate-pulse" />}
                            {streams.length} ACTIVE_NODES
                        </div>
                    </div>

                    <div className="flex items-center gap-4">
                        <button onClick={() => fetchStreams()} className="p-2 border border-[var(--color-iron)] hover:border-white text-[var(--color-silica)] transition-colors" title="Refresh Feed">
                            <RefreshCw className="w-4 h-4" />
                        </button>

                        <button onClick={() => setIsDialogOpen(true)} className="px-6 py-2 border-[2px] border-[var(--color-data)] font-bold text-[10px] text-black bg-[var(--color-data)] hover:bg-white transition-none shadow-[4px_4px_0_var(--color-data)] active:translate-x-[2px] active:translate-y-[2px] active:shadow-[2px_2px_0_var(--color-data)] flex items-center gap-2">
                            <PlusSquare className="w-3 h-3" /> [ DEPLOY_SENSOR ]
                        </button>
                    </div>
                </div>

                <div className="flex-1 grid grid-cols-1 md:grid-cols-3 grid-rows-2 gap-[2px] bg-[var(--color-iron)] border-[2px] border-[var(--color-iron)] overflow-hidden">

                    {primaryStream ? (
                        <div className="md:col-span-2 md:row-span-2 h-full relative border-r-[2px] border-b-[2px] border-[var(--color-iron)]">
                            <div className="absolute inset-0 z-40 flex items-start justify-between p-2 pointer-events-none">
                                <span className="bg-black text-[var(--color-data)] px-2 font-bold text-[10px] border-[1px] border-[var(--color-iron)]">NODE_01 [PRIORITY]</span>
                            </div>
                            <StreamNode
                                key={primaryStream.id}
                                stream={primaryStream}
                                onDelete={handleDeleteStream}
                                onDetections={handleDetections}
                                isPrimary={true}
                            />
                        </div>
                    ) : (
                        <div className="md:col-span-2 md:row-span-2 relative bg-black flex flex-col items-center justify-center overflow-hidden border-r-[2px] border-[var(--color-iron)]">
                            <span className="font-bold text-[var(--color-silica)] text-sm tracking-widest border border-current px-4 py-2">[ GRID_OFFLINE ]</span>
                        </div>
                    )}

                    {secondaryStreams.map(s => (
                        <StreamNode
                            key={s.id}
                            stream={s}
                            onDelete={handleDeleteStream}
                            onDetections={handleDetections}
                            isPrimary={false}
                        />
                    ))}

                    {/* Fill empty spots */}
                    {placeholders.map((_, i) => (
                        <div key={`ph-${i}`} className="relative bg-[#0A0A0A] flex flex-col hover:border-[var(--color-iron)] overflow-hidden pointer-events-none">
                            <div className="p-2 flex justify-between z-30 pointer-events-none bg-black border-b-[2px] border-[var(--color-iron)]">
                                <span className="text-[var(--color-silica)] px-1 font-bold text-[8px]">NODE_STANDBY</span>
                                <span className="text-[#333] px-1 font-bold text-[8px]">OFFLINE</span>
                            </div>
                            <div className="flex-1 flex items-center justify-center font-bold text-[10px] text-[var(--color-iron)] relative">
                                <div className="absolute inset-0 bg-[linear-gradient(rgba(51,51,51,0.5)_0.5px,transparent_0.5px),linear-gradient(90deg,rgba(51,51,51,0.5)_0.5px,transparent_0.5px)] bg-[size:16px_16px] opacity-[0.05]" />
                                <span className="border border-current px-2 py-1 bg-black z-10">NO_VIDEO_SIGNAL</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="w-80 min-w-[320px] shadow-[var(--shadow-md)]">
                <AlertSidebar
                    alerts={alerts}
                    onClear={(id) => setAlerts(prev => prev.filter(a => a.id !== id))}
                    onClearAll={() => setAlerts([])}
                />
            </div>

            <StreamDialog
                isOpen={isDialogOpen}
                onClose={() => setIsDialogOpen(false)}
                onStreamAdded={() => {
                    fetchStreams();
                    logSysEvent("[INFO] SENSOR PROXY DEPLOYED TO THREAT MATRIX");
                }}
            />
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import VideoUpload from "@/components/VideoUpload";
import VideoPlayer from "@/components/VideoPlayer";
import AlertSidebar from "@/components/AlertSidebar";

export default function UploadAnalysisPage() {
    const [videoData, setVideoData] = useState<any>(null);
    const [alerts, setAlerts] = useState<any[]>([]);
    const [models, setModels] = useState<any[]>([]);
    const [selectedModel, setSelectedModel] = useState<string>("latest");
    const [confidenceThreshold, setConfidenceThreshold] = useState<number>(0.50);

    useEffect(() => {
        fetch("http://localhost:8000/api/models")
            .then(res => res.json())
            .then(data => {
                if (data.models) setModels(data.models);
            })
            .catch(err => console.error("Failed to fetch models", err));
    }, []);

    const [seekTrigger, setSeekTrigger] = useState<{ time: number, id: number } | null>(null);

    const handleUploadComplete = (data: any) => {
        setVideoData(data);
        setAlerts([]);
    };

    const handleNewAlerts = (detections: any[], timestamp: number) => {
        const newThreats = detections.filter(
            d => ["rifle", "handgun", "knife", "weapon"].includes(d.class_name) && d.confidence >= confidenceThreshold
        );

        const activeEvents = [...newThreats];

        if (activeEvents.length > 0) {
            setAlerts(prev => {
                let updated = [...prev];
                activeEvents.forEach(event => {
                    const existingIdx = updated.findIndex(a =>
                        a.class_name === event.class_name &&
                        a.endTimestamp !== undefined &&
                        (timestamp - a.endTimestamp) <= 3.0
                    );

                    if (existingIdx !== -1) {
                        updated[existingIdx] = {
                            ...updated[existingIdx],
                            endTimestamp: Math.max(updated[existingIdx].endTimestamp, timestamp),
                            confidence: Math.max(updated[existingIdx].confidence, event.confidence)
                        };
                    } else {
                        updated.unshift({
                            id: Date.now() + Math.random(),
                            class_name: event.class_name,
                            confidence: event.confidence,
                            startTimestamp: timestamp,
                            endTimestamp: timestamp
                        });
                    }
                });
                return updated.slice(0, 50);
            });
        }
    };

    return (
        <div className="flex gap-6 h-[calc(100vh-8rem)] font-mono uppercase tracking-widest text-[#FFF]">

            {/* Left side: Upload/Analysis Matrix */}
            <div className="flex-1 flex flex-col border-[2px] border-[var(--color-iron)] bg-black overflow-hidden relative">

                {!videoData ? (
                    // Ingestion State
                    <div className="flex-1 w-full flex flex-col relative">
                        <div className="p-4 border-b-[2px] border-[var(--color-iron)] bg-[var(--color-dim)] font-bold text-xs">
                            [ ARCHIVE_INGESTION_MODULE ]
                        </div>
                        <div className="flex-1 p-8 lg:p-16 flex items-center justify-center">
                            <div className="w-full h-full max-w-3xl border-2 border-dashed border-[var(--color-iron)] bg-[#050505] hover:border-[var(--color-data)] hover:bg-[var(--color-dim)] transition-none p-2 relative flex flex-col">
                                {/* Decorators */}
                                <div className="absolute top-0 left-0 w-4 h-4 border-t-[2px] border-l-[2px] border-[var(--color-data)] -translate-x-[2px] -translate-y-[2px]" />
                                <div className="absolute top-0 right-0 w-4 h-4 border-t-[2px] border-r-[2px] border-[var(--color-data)] translate-x-[2px] -translate-y-[2px]" />
                                <div className="absolute bottom-0 left-0 w-4 h-4 border-b-[2px] border-l-[2px] border-[var(--color-data)] -translate-x-[2px] translate-y-[2px]" />
                                <div className="absolute bottom-0 right-0 w-4 h-4 border-b-[2px] border-r-[2px] border-[var(--color-data)] translate-x-[2px] translate-y-[2px]" />

                                {/* We inject the original VideoUpload but it's wrapped in our UI */}
                                <div className="flex-1 w-full flex items-center justify-center relative z-10">
                                    <VideoUpload onUploadComplete={handleUploadComplete} />
                                </div>
                            </div>
                        </div>
                    </div>
                ) : (
                    // Analysis State
                    <div className="w-full h-full flex flex-col">

                        {/* Control Strip */}
                        <div className="flex items-center justify-between border-b-[2px] border-[var(--color-iron)] bg-black p-4 shrink-0">
                            <div>
                                <h2 className="font-bold text-sm bg-[var(--color-data)] text-black inline-block px-2">{videoData.filename}</h2>
                                <p className="text-[10px] text-[var(--color-silica)] mt-1">
                                    [ LEN: {videoData.duration?.toFixed(2)}s | FPS: {videoData.fps?.toFixed(0)} | RES: {videoData.resolution?.width}x{videoData.resolution?.height} ]
                                </p>
                            </div>

                            <div className="flex items-center gap-6">
                                <div className="flex flex-col gap-1 w-32">
                                    <div className="flex justify-between text-[10px] font-bold">
                                        <span className="text-[var(--color-silica)]">CONFIDENCE</span>
                                        <span className="text-[var(--color-alert)]">{(confidenceThreshold * 100).toFixed(0)}%</span>
                                    </div>
                                    <input
                                        type="range"
                                        min="0.1" max="0.95" step="0.05"
                                        value={confidenceThreshold}
                                        onChange={(e) => setConfidenceThreshold(parseFloat(e.target.value))}
                                        className="w-full appearance-none h-1 bg-[var(--color-dim)] border border-[var(--color-iron)] outline-none cursor-crosshair accent-[var(--color-alert)]"
                                    />
                                </div>

                                <button
                                    onClick={() => setVideoData(null)}
                                    className="px-4 py-2 text-[10px] font-bold border-[2px] border-[var(--color-iron)] hover:border-[var(--color-data)] hover:bg-[var(--color-data)] hover:text-black transition-none uppercase shadow-[4px_4px_0_var(--color-iron)] active:translate-x-[2px] active:translate-y-[2px] active:shadow-[2px_2px_0_var(--color-iron)] text-[var(--color-silica)]"
                                >
                                    [ CLEAR_BUFFER ]
                                </button>
                            </div>
                        </div>

                        {/* Video Forensic Player */}
                        <div className="flex-1 relative bg-[#050505] p-4 flex items-center justify-center overflow-hidden">
                            <div className="absolute inset-0 bg-[linear-gradient(rgba(51,51,51,0.5)_1px,transparent_1px),linear-gradient(90deg,rgba(51,51,51,0.5)_1px,transparent_1px)] bg-[size:32px_32px] opacity-20 pointer-events-none z-0" />

                            <div className="w-full max-w-5xl border-[2px] border-[var(--color-iron)] relative z-10 shadow-2xl">
                                {/* Decorators */}
                                <div className="absolute top-0 left-0 w-2 h-2 border-t-[2px] border-l-[2px] border-[var(--color-data)] -translate-x-[2px] -translate-y-[2px] z-20" />
                                <div className="absolute bottom-0 right-0 w-2 h-2 border-b-[2px] border-r-[2px] border-[var(--color-data)] translate-x-[2px] translate-y-[2px] z-20" />

                                <VideoPlayer
                                    videoId={videoData.video_id}
                                    videoUrl={videoData.file_url}
                                    modelId={selectedModel}
                                    confidenceThreshold={confidenceThreshold}
                                    onAlert={handleNewAlerts}
                                    seekTrigger={seekTrigger}
                                />
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Right Side: Brutalist Alert Log */}
            {videoData && (
                <div className="w-80 min-w-[320px] shadow-[var(--shadow-md)] flex-shrink-0">
                    <AlertSidebar
                        alerts={alerts}
                        onSeek={(time) => setSeekTrigger({ time, id: Date.now() })}
                        onClear={(id) => setAlerts(prev => prev.filter(a => a.id !== id))}
                        onClearAll={() => setAlerts([])}
                    />
                </div>
            )}
        </div>
    );
}

"use client";

import { useAuth } from "@/context/AuthContext";
import { useRouter, usePathname } from "next/navigation";
import { useEffect } from "react";
import Link from "next/link";
import { auth } from "@/lib/firebase";
import { signOut } from "firebase/auth";
import { TelemetryProvider } from "@/context/TelemetryContext";

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
    const { user, loading } = useAuth();
    const router = useRouter();
    const pathname = usePathname();

    useEffect(() => {
        if (!loading && !user) {
            router.push("/login");
        }
    }, [user, loading, router]);

    if (loading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[var(--color-void)] font-mono text-[var(--color-alert)] text-sm tracking-widest font-bold">
                [ ESTABLISHING_SECURE_CONNECTION... ]
            </div>
        );
    }

    const handleLogout = async () => {
        await signOut(auth);
        router.push("/");
    };

    return (
        <div className="flex h-screen bg-[var(--color-void)] font-sans uppercase tracking-tight text-[var(--color-data)] overflow-hidden selection:bg-[var(--color-alert)] selection:text-black">

            {/* Sidebar - Pure Functional Brutalism */}
            <aside className="w-64 bg-black border-r-[2px] border-[var(--color-iron)] flex flex-col relative z-20 flex-shrink-0">
                <div className="absolute inset-0 bg-[linear-gradient(rgba(51,51,51,0.5)_1px,transparent_1px),linear-gradient(90deg,rgba(51,51,51,0.5)_1px,transparent_1px)] bg-[size:32px_32px] opacity-10 pointer-events-none" />

                <div className="px-6 py-4 border-b-[2px] border-[var(--color-iron)] flex items-center gap-2 relative z-10">
                    <div className="w-3 h-3 bg-[var(--color-alert)] animate-[pulse_2s_ease-in-out_infinite]" />
                    <span className="font-mono font-bold text-xl text-[var(--color-data)]">AEGIS_OS</span>
                </div>

                <div className="px-6 py-2 border-b-[2px] border-[var(--color-iron)] font-mono text-[10px] text-[var(--color-silica)] bg-[var(--color-dim)] relative z-10 flex flex-col">
                    <span>DIR: ROOT/OPERATIONS</span>
                    <span className="text-[var(--color-alert)] mt-1">ACCESS_LEVEL: ADMIN</span>
                </div>

                <nav className="flex-1 flex flex-col pt-4 relative z-10 font-mono text-xs font-bold tracking-widest">
                    <Link
                        href="/dashboard"
                        className={`px-6 py-4 flex items-center justify-between border-y border-transparent transition-none ${pathname === '/dashboard' ? 'bg-[var(--color-data)] text-black border-[var(--color-data)]' : 'text-[var(--color-silica)] hover:text-white hover:bg-[var(--color-dim)] hover:border-[var(--color-iron)] group'}`}
                    >
                        [ OVERVIEW ]
                        {pathname === '/dashboard' && <span className="animate-pulse">_</span>}
                    </Link>
                    <Link
                        href="/dashboard/upload"
                        className={`px-6 py-4 flex items-center justify-between border-y border-transparent transition-none ${pathname.includes('/upload') ? 'bg-[var(--color-data)] text-black border-[var(--color-data)]' : 'text-[var(--color-silica)] hover:text-white hover:bg-[var(--color-dim)] hover:border-[var(--color-iron)]'}`}
                    >
                        [ ARCHIVE_REPLAY ]
                        {pathname.includes('/upload') && <span className="animate-pulse">_</span>}
                    </Link>
                    <Link
                        href="/dashboard/live"
                        className={`px-6 py-4 flex items-center justify-between border-y border-transparent transition-none ${pathname.includes('/live') ? 'bg-[var(--color-alert)] text-black border-[var(--color-alert)]' : 'text-[var(--color-alert)] hover:bg-black hover:border-[var(--color-alert)] opacity-70 hover:opacity-100'}`}
                    >
                        [ LIVE_INFERENCE ]
                        {pathname.includes('/live') && <span className="animate-pulse">_</span>}
                    </Link>
                    <Link
                        href="/dashboard/settings"
                        className={`px-6 py-4 flex items-center justify-between border-y border-transparent transition-none ${pathname.includes('/settings') ? 'bg-[var(--color-data)] text-black border-[var(--color-data)]' : 'text-[var(--color-silica)] hover:text-white hover:bg-[var(--color-dim)] hover:border-[var(--color-iron)]'}`}
                    >
                        [ SYSTEM_CONFIG ]
                        {pathname.includes('/settings') && <span className="animate-pulse">_</span>}
                    </Link>
                </nav>

                <div className="border-t-[2px] border-[var(--color-iron)] relative z-10 bg-black">
                    <button
                        onClick={handleLogout}
                        className="w-full text-left px-6 py-4 font-mono text-xs font-bold tracking-widest text-[var(--color-silica)] hover:bg-[var(--color-alert)] hover:text-black transition-none uppercase"
                    >
                        [ TERMINATE_SESSION ]
                    </button>
                </div>
            </aside>

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col min-w-0 bg-[var(--color-dim)] relative">

                {/* Header Top Bar */}
                <header className="h-14 border-b-[2px] border-[var(--color-iron)] flex items-center justify-between px-6 bg-black z-10 flex-shrink-0">
                    <h2 className="font-mono font-bold text-sm text-[var(--color-data)]">
                        {pathname === '/dashboard' ? 'SYS.OVERVIEW_Telemetry' : pathname.includes('live') ? 'SYS.LIVE_Inference_Stream' : 'SYS.ARCHIVE_Analysis'}
                    </h2>
                    <div className="flex items-center gap-4 bg-[var(--color-iron)] pl-2 pr-1 py-1">
                        <span className="font-mono text-[10px] text-white">OP_ID: {user.email}</span>
                        <div className="w-4 h-4 bg-black border border-white flex items-center justify-center font-mono text-[8px] text-white font-bold">
                            {user.email?.charAt(0).toUpperCase()}
                        </div>
                    </div>
                </header>

                {/* Sub Header / Breadcrumb Bar */}
                <div className="h-8 border-b-[2px] border-[var(--color-iron)] bg-[var(--color-void)] flex items-center px-6 font-mono text-[10px] text-[var(--color-silica)] flex-shrink-0">
                    WORKSPACE // {pathname.replace('/', '').toUpperCase() || 'DASHBOARD'} // {new Date().toISOString()} // SECURE_SOCKET_ESTABLISHED
                </div>

                {/* Scrollable Main Content */}
                <main className="flex-1 overflow-y-auto p-6 relative z-10 font-sans custom-scrollbar">
                    <TelemetryProvider>
                        {children}
                    </TelemetryProvider>
                </main>
            </div>
        </div>
    );
}

"use client";

import Link from "next/link";
import { useEffect, useState, useRef, useMemo } from "react";
import { motion, useScroll, useTransform, AnimatePresence, useSpring } from "framer-motion";

// High-end Brutalist text decoder animation
const ScrambleText = ({ text, delay = 0, durationMultiplier = 1, className = "" }: { text: string; delay?: number; durationMultiplier?: number; className?: string }) => {
    const [displayText, setDisplayText] = useState("");
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$*&%";

    useEffect(() => {
        let iteration = 0;
        let animationFrame: number;
        let startTimeout: NodeJS.Timeout;

        const startAnimation = () => {
            const animate = () => {
                setDisplayText(text.split("").map((letter, index) => {
                    if (index < iteration || letter === " ") return text[index];
                    return chars[Math.floor(Math.random() * chars.length)];
                }).join(""));

                if (iteration >= text.length) {
                    cancelAnimationFrame(animationFrame);
                    setDisplayText(text);
                    return;
                }
                iteration += (1 / 3) / durationMultiplier;
                animationFrame = requestAnimationFrame(animate);
            };
            animate();
        };

        startTimeout = setTimeout(startAnimation, delay);

        return () => {
            clearTimeout(startTimeout);
            cancelAnimationFrame(animationFrame);
        };
    }, [text, delay, durationMultiplier]);

    return (
        <span className={`inline-block relative whitespace-nowrap ${className}`}>
            <span className="opacity-0 pointer-events-none select-none">{text}</span>
            <span className="absolute top-0 left-0 bottom-0 whitespace-nowrap font-mono">{displayText || " "}</span>
        </span>
    );
};

const useInView = (options = {}) => {
    const ref = useRef(null);
    const [isInView, setIsInView] = useState(false);

    useEffect(() => {
        const observer = new IntersectionObserver(([entry]) => {
            if (entry.isIntersecting) setIsInView(true);
        }, { threshold: 0.1, ...options });

        if (ref.current) observer.observe(ref.current);
        return () => observer.disconnect();
    }, [options]);

    return [ref, isInView] as const;
};

