"use client";

import { useEffect, useRef, useState } from "react";
import { Trash2, AlertTriangle, Square } from "lucide-react";
import { auth } from "@/lib/firebase";

interface StreamNodeProps {
    stream: any;
    onDelete: (id: string, cascadeDelete: boolean) => void;
    onDetections: (detections: any[], timestamp: number) => void;
    isPrimary?: boolean;
}

export default function StreamNode({ stream, onDelete, onDetections, isPrimary = false }: StreamNodeProps) {
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const overlayRef = useRef<HTMLCanvasElement>(null);
    const wsInRef = useRef<WebSocket | null>(null);
    const wsOutRef = useRef<WebSocket | null>(null);

    const [isStreaming, setIsStreaming] = useState(false);
    const [latestImage, setLatestImage] = useState<string | null>(null);

    const isOwnerOfClientCam = stream.type === "client_cam" && stream.uid === (auth.currentUser?.uid || "anonymous");

    const stopLocalStream = () => {
        if (videoRef.current && videoRef.current.srcObject) {
            const mediaStream = videoRef.current.srcObject as MediaStream;
            mediaStream.getTracks().forEach(track => track.stop());
            videoRef.current.srcObject = null;
        }
        setIsStreaming(false);
    };

    useEffect(() => {
        let isActive = true;

        const initStream = async () => {
            if (isOwnerOfClientCam) {
                // We are the publisher
                try {
                    const mediaStream = await navigator.mediaDevices.getUserMedia({ video: { width: 1280, height: 720 } });
                    if (videoRef.current) {
                        videoRef.current.srcObject = mediaStream;
                        videoRef.current.play();
                        setIsStreaming(true);
                    }

                    wsInRef.current = new WebSocket(`ws://localhost:8000/ws/stream_in/${stream.id}`);
                    wsInRef.current.onopen = () => {
                        requestAnimationFrame(sendFrame);
                    };

                    wsInRef.current.onmessage = (event) => {
                        const data = JSON.parse(event.data);
                        if (data.detections) {
                            drawDetections(data.detections);
                            onDetections(data.detections, data.timestamp);
                        }
                    };

                } catch (err) {
                    console.error("Local webcam error:", err);
                }
            } else {
                // We are the consumer (or looking at an RTSP/Server stream)
                wsOutRef.current = new WebSocket(`ws://localhost:8000/ws/stream_out/${stream.id}`);
                wsOutRef.current.onmessage = (event) => {
                    const data = JSON.parse(event.data);
                    if (data.image) {
                        setLatestImage(data.image);
                        setIsStreaming(true);
                    }
                    if (data.detections) {
                        drawDetections(data.detections);
                        onDetections(data.detections, data.timestamp);
                    }
                };
            }
        };

        initStream();

        return () => {
            isActive = false;
            stopLocalStream();
            if (wsInRef.current) wsInRef.current.close();
            if (wsOutRef.current) wsOutRef.current.close();
        };
    }, [stream.id, isOwnerOfClientCam]);

    const sendFrame = () => {
        if (!isStreaming || !videoRef.current || !canvasRef.current || !wsInRef.current || wsInRef.current.readyState !== WebSocket.OPEN) {
            if (isStreaming) setTimeout(() => requestAnimationFrame(sendFrame), 100);
            return;
        }
        const video = videoRef.current;
        const canvas = canvasRef.current;

        if (canvas.width !== video.videoWidth) canvas.width = video.videoWidth;
        if (canvas.height !== video.videoHeight) canvas.height = video.videoHeight;
        if (overlayRef.current) {
            if (overlayRef.current.width !== video.videoWidth) overlayRef.current.width = video.videoWidth;
            if (overlayRef.current.height !== video.videoHeight) overlayRef.current.height = video.videoHeight;
        }

        const ctx = canvas.getContext("2d");
        if (ctx && video.readyState >= 2) {
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            const dataUrl = canvas.toDataURL("image/jpeg", 0.6);

            wsInRef.current.send(JSON.stringify({
                type: "frame",
                timestamp: Date.now(),
                image: dataUrl
            }));
        }

        setTimeout(() => {
            if (isStreaming) requestAnimationFrame(sendFrame);
        }, 150);
    };

    const drawDetections = (detections: any[]) => {
        if (!overlayRef.current) return;

        let targetWidth = overlayRef.current.width;
        let targetHeight = overlayRef.current.height;

        // If not rendering video, render image bounds 
        // We ensure canvas matches intrinsic size in an effect usually, but let's assume it resizes.
        if (!isOwnerOfClientCam) {
            const img = new Image();
            if (latestImage) img.src = latestImage;
            targetWidth = overlayRef.current.clientWidth || 1280;
            targetHeight = overlayRef.current.clientHeight || 720;
            overlayRef.current.width = targetWidth;
            overlayRef.current.height = targetHeight;
        }

        const ctx = overlayRef.current.getContext("2d");
        if (!ctx) return;
        ctx.clearRect(0, 0, targetWidth, targetHeight);

        detections.forEach((det: any) => {
            if (det.confidence < 0.45) return;
            const x1 = det.bbox[0] * targetWidth;
            const y1 = det.bbox[1] * targetHeight;
            const x2 = det.bbox[2] * targetWidth;
            const y2 = det.bbox[3] * targetHeight;
            const isWeapon = ["rifle", "handgun", "knife", "weapon"].includes(det.class_name);
            const color = isWeapon ? "#FF3300" : "#FFFFFF";

            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(x1, y1 + 10); ctx.lineTo(x1, y1); ctx.lineTo(x1 + 10, y1);
            ctx.moveTo(x2 - 10, y1); ctx.lineTo(x2, y1); ctx.lineTo(x2, y1 + 10);
            ctx.moveTo(x2, y2 - 10); ctx.lineTo(x2, y2); ctx.lineTo(x2 - 10, y2);
            ctx.moveTo(x1 + 10, y2); ctx.lineTo(x1, y2); ctx.lineTo(x1, y2 - 10);
            ctx.stroke();

            ctx.fillStyle = color;
            ctx.fillRect(x1, y1 - 20, isWeapon ? 120 : 80, 20);
            ctx.fillStyle = "#000000";
            ctx.font = "bold 10px monospace";
            ctx.fillText(`${det.class_name.toUpperCase()} ${(det.confidence * 100).toFixed(0)}%`, x1 + 4, y1 - 6);
        });
    };

    const handleDelete = async () => {
        const confirmed = window.confirm(`Terminate ${stream.name}? This removes it for all users.`);
        if (confirmed) {
            onDelete(stream.id, true);
        }
    };

    return (
        <div className={`relative bg-[#0A0A0A] flex flex-col group ${isPrimary ? "md:col-span-2 md:row-span-2 border-[2px] border-[var(--color-iron)]" : "border-b-[2px] border-[var(--color-dim)] overflow-hidden hover:border-[var(--color-iron)]"}`}>
            {isPrimary && <div className="absolute inset-0 bg-[linear-gradient(rgba(51,51,51,0.5)_1px,transparent_1px),linear-gradient(90deg,rgba(51,51,51,0.5)_1px,transparent_1px)] bg-[size:32px_32px] opacity-10 pointer-events-none z-0" />}

            {/* Overlay Frame */}
            <div className="absolute top-4 left-4 border-l-[2px] border-t-[2px] border-[var(--color-silica)] w-8 h-8 z-30 pointer-events-none opacity-50" />
            <div className="absolute top-4 right-4 border-r-[2px] border-t-[2px] border-[var(--color-silica)] w-8 h-8 z-30 pointer-events-none opacity-50" />
            <div className="absolute bottom-4 left-4 border-l-[2px] border-b-[2px] border-[var(--color-silica)] w-8 h-8 z-30 pointer-events-none opacity-50" />
            <div className="absolute bottom-4 right-4 border-r-[2px] border-b-[2px] border-[var(--color-silica)] w-8 h-8 z-30 pointer-events-none opacity-50" />

            <div className={`p-2 flex justify-between z-30 bg-gradient-to-b from-black/80 to-transparent ${!isPrimary && "bg-black border-b-[2px] border-[var(--color-iron)]"} absolute top-0 left-0 w-full`}>
                <span className={`bg-black text-[var(--color-data)] px-2 font-bold ${isPrimary ? "text-[10px]" : "text-[8px]"} border-[1px] border-[var(--color-iron)] truncate max-w-[150px]`}>
                    {stream.name} [{stream.type.toUpperCase()}]
                </span>
                <div className="flex gap-2">
                    <span className={`bg-black px-2 font-bold ${isPrimary ? "text-[10px]" : "text-[8px]"} border-[1px] border-[var(--color-iron)] ${isStreaming ? 'text-[var(--color-alert)] animate-pulse' : 'text-[#333]'}`}>
                        {isStreaming ? 'REC' : 'WAITING'}
                    </span>
                    <button onClick={handleDelete} className="bg-black text-[var(--color-iron)] hover:text-red-500 hover:border-red-500 border border-[var(--color-iron)] px-1">
                        <Trash2 className="w-3 h-3" />
                    </button>
                </div>
            </div>

            <div className="relative flex-1 w-full h-full flex items-center justify-center overflow-hidden z-20">
                {!isStreaming && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-[var(--color-silica)] z-10 w-full h-full">
                        <Square className="w-8 h-8 mb-4 border-[2px] border-current p-1 opacity-50" />
                        <p className="font-bold text-[10px] tracking-widest text-[#555]">[ AWAITING_FEED ]</p>
                    </div>
                )}

                {isOwnerOfClientCam ? (
                    <>
                        <video ref={videoRef} className={`h-full w-full object-cover ${isStreaming ? 'opacity-100' : 'opacity-0'}`} muted playsInline />
                        <canvas ref={canvasRef} className="hidden" />
                    </>
                ) : (
                    latestImage && <img src={latestImage} className="w-full h-full object-cover" alt="stream" />
                )}

                <canvas ref={overlayRef} className="absolute top-0 left-0 w-full h-full object-cover pointer-events-none mix-blend-screen" />
            </div>
        </div>
    );
}

"use client";

import { useEffect, useRef, useState } from "react";

export default function VideoPlayer({
    videoUrl,
    videoId,
    modelId,
    confidenceThreshold,
    onAlert,
    seekTrigger
}: {
    videoUrl: string;
    videoId: string;
    modelId: string;
    confidenceThreshold: number;
    onAlert: (detections: any, timestamp: number) => void;
    seekTrigger?: { time: number, id: number } | null;
}) {
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    const wsRef = useRef<WebSocket | null>(null);

    useEffect(() => {
        if (seekTrigger && videoRef.current) {
            videoRef.current.currentTime = seekTrigger.time;
            videoRef.current.play();
        }
    }, [seekTrigger]);

    useEffect(() => {
        // Setup WebSocket
        const ws = new WebSocket(`ws://localhost:8000/ws/detect/${videoId}?model=${encodeURIComponent(modelId)}`);
        wsRef.current = ws;

        ws.onmessage = (event) => {
            const data = JSON.parse(event.data);
            if (data.detections && data.detections.length > 0) {
                onAlert(data.detections, data.timestamp);

                // Immediately paint these latest detections on the canvas
                const canvas = canvasRef.current;
                const video = videoRef.current;
                if (!canvas || !video) return;

                const ctx = canvas.getContext("2d");
                if (!ctx) return;

                const { videoWidth, videoHeight } = video;
                if (!videoWidth || !videoHeight) return;

                // Sync intrinsic dimensions
                if (canvas.width !== videoWidth) canvas.width = videoWidth;
                if (canvas.height !== videoHeight) canvas.height = videoHeight;

                ctx.clearRect(0, 0, canvas.width, canvas.height);

                data.detections.forEach((d: any) => {
                    const { x1: nx1, y1: ny1, x2: nx2, y2: ny2 } = d.bbox;

                    // Filter out detections below the user's selected threshold
                    if (d.confidence < confidenceThreshold) return;

                    let color = "gray"; // person
                    if (["rifle", "handgun", "knife"].includes(d.class_name)) color = "red";
                    if (["umbrella", "chip_bag"].includes(d.class_name)) color = "yellow";

                    // Map normalized coordinates 0->1 to exact canvas pixel geometry
                    const px1 = nx1 * canvas.width;
                    const py1 = ny1 * canvas.height;
                    const px2 = nx2 * canvas.width;
                    const py2 = ny2 * canvas.height;

                    const sw = px2 - px1;
                    const sh = py2 - py1;

                    ctx.strokeStyle = color;
                    ctx.lineWidth = 3;
                    ctx.strokeRect(px1, py1, sw, sh);

                    ctx.fillStyle = color;
                    ctx.font = "16px Arial";

                    // Background for text
                    const text = `${d.class_name} ${(d.confidence * 100).toFixed(0)}%`;
                    const textWidth = ctx.measureText(text).width;
                    ctx.fillRect(px1, py1 - 24, textWidth + 8, 24);

                    ctx.fillStyle = "white";
                    ctx.fillText(text, px1 + 4, py1 - 6);
                });
            } else {
                // Clear canvas if no detections are returned
                const canvas = canvasRef.current;
                if (canvas) {
                    const ctx = canvas.getContext("2d");
                    if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
                }
            }
        };

        return () => {
            ws.close();
            wsRef.current = null;
        }
    }, [videoId, modelId, onAlert, confidenceThreshold]);

    // Hidden extraction loop to encode active frames directly from the HTML5 player
    useEffect(() => {
        const interval = setInterval(() => {
            const video = videoRef.current;
            const ws = wsRef.current;

            if (!video || !ws || ws.readyState !== WebSocket.OPEN) return;
            if (video.paused || video.ended) return;

            // Extract real-time screen data specifically at high-perf 640x640 (standard RT-DETR/YOLO grid)
            const captureCanvas = document.createElement("canvas");
            captureCanvas.width = 640;
            captureCanvas.height = 640;

            const ctx = captureCanvas.getContext("2d");
            if (!ctx) return;

            // Draw current video state
            ctx.drawImage(video, 0, 0, 640, 640);

            // Convert to lightweight base64 JPEG
            const base64Str = captureCanvas.toDataURL("image/jpeg", 0.7);

            ws.send(JSON.stringify({
                type: "frame",
                image: base64Str,
                timestamp: video.currentTime
            }));

        }, 125); // ~8 FPS extraction (fast enough for real-time smoothness without overloading Websockets)

        return () => clearInterval(interval);
    }, []);

    return (
        <div className="relative w-full aspect-video bg-black rounded overflow-hidden">
            <video
                ref={videoRef}
                src={`http://localhost:8000${videoUrl}`}
                controls
                className="w-full h-full object-contain"
                crossOrigin="anonymous"
            />
            <canvas
                ref={canvasRef}
                className="absolute top-0 left-0 w-full h-full pointer-events-none object-contain"
            />
        </div>
    );
}

